import {allActions,OMEN_RULES,craftedLimit} from './craft-engine.mjs';
import {createWorkbench} from './advanced-ui.mjs';
import {caps,conflict,allowed,families,tier,progress,total,validateProject} from './engine.mjs';
const DATA=window.FORGE_DATA, $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('ru-RU',{maximumFractionDigits:2});
const CURRENCIES=[['Exalted Orb','Сфера возвышения',''],['Chaos Orb','Сфера хаоса','chaos'],['Divine Orb','Божественная сфера',''],['Regal Orb','Сфера царей','regal'],['Orb of Augmentation','Сфера усиления','regal'],['Orb of Transmutation','Сфера превращения','regal'],['Orb of Alchemy','Сфера алхимии',''],['Orb of Annulment','Сфера отмены','chaos'],['Essence','Эссенция','regal'],['Omen','Знамение','chaos'],['Base','Стоимость базы',''],['Other','Другое','']];
for(const row of [...window.CRAFTING_DATA.omens,...window.CRAFTING_DATA.essences,...window.CRAFTING_DATA.quality,...window.CRAFTING_DATA.currencies,...DATA.groups.flatMap(g=>allActions(g,window.CRAFTING_DATA))]){const id=(row.currency||row.id).replaceAll('_',' ');if(!CURRENCIES.some(c=>c[0]===id))CURRENCIES.push([id,row.name,''])}
const KEY='wraeclast-forge-v1';let page='craft',store={projects:[],active:null,rates:{'Exalted Orb':1}},timer;
try{const s=JSON.parse(localStorage.getItem(KEY));if(s?.projects?.length){store={...store,...s,projects:s.projects.map(p=>({...validateProject(p,DATA),id:p.id}))};if(!store.projects.some(p=>p.id===store.active))store.active=store.projects[0].id}}catch{ }
function blank(group='Bows',base){const g=DATA.groups.find(g=>g.id===group);return {id:crypto.randomUUID(),name:'Новый крафт',group,base:base||g.bases[0].id,level:82,rarity:'normal',quality:0,sockets:0,augments:[],history:[],leagueMode:'current',mods:[],targets:[],entries:[],budget:100,corrupted:false,updated:Date.now()}}
function demo(){const p=blank('Bows','Gemini_Bow');p.name='Физический лук';return p}
if(!store.projects.length){const p=demo();store.projects=[p];store.active=p.id}
const current=()=>store.projects.find(p=>p.id===store.active),group=()=>DATA.groups.find(g=>g.id===current().group),base=()=>group().bases.find(b=>b.id===current().base),mods=()=>current().mods.map(x=>({...group().mods.find(m=>m.id===x.id),...x}));
function persist(){try{localStorage.setItem(KEY,JSON.stringify(store));$('#save-state').innerHTML='<span class="green-dot"></span> Сохранено на устройстве'}catch{$('#save-state').textContent='Не удалось сохранить';toast('Хранилище недоступно. Экспортируйте проект.')}}
function save(renderPage=true){current().updated=Date.now();persist();if(renderPage)render()}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function modal(title,body,actions=''){if($('#modal').open)$('#modal').close();$('#modal-content').innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="icon-button" id="close-modal" aria-label="Закрыть">×</button></div><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;$('#close-modal').onclick=()=>$('#modal').close();$('#modal').showModal()}
function countLabel(){const p=current(),gs=progress(p,group());return `${gs.filter(x=>x.met).length} / ${gs.length}`}
function render(){document.querySelectorAll('[data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===page));$('#project-count').textContent=store.projects.length;$('#breadcrumb').textContent=({craft:'Крафт предмета',projects:'Мои проекты',journal:'Журнал валюты'})[page];$('#main').innerHTML=page==='craft'?craftHTML():page==='projects'?projectsHTML():journalHTML();bind();workbench.bind();}
function art(b){return `<div class="item-art"><img src="${esc(b.img)}" alt="${esc(b.name)}" onerror="this.style.opacity='.15'"></div>`}
function craftHTML(){const p=current(),g=group(),b=base(),ms=mods(),gs=progress(p,g),spent=total(p.entries),weight=gs.reduce((n,t)=>n+t.priority,0),done=gs.reduce((n,t)=>n+(t.met?t.priority:0),0),percent=weight?Math.round(done/weight*100):0;return `<div class="page-heading"><div><div class="eyebrow">ИЗ ХОРОШЕЙ БАЗЫ — В ИДЕАЛЬНУЮ ВЕЩЬ</div><input id="project-name" class="title-input" aria-label="Название проекта" maxlength="120" value="${esc(p.name)}"><p>Ваша вещь. Ваши цели. Каждый шаг под контролем.</p></div><span class="heading-stamp">CRAFTING WORKSPACE / 01</span></div><div class="steps"><span class="step active"><i>1</i> Выберите базу</span><span class="step-line"></span><span class="step active"><i>2</i> Выберите статы</span><span class="step-line"></span><span class="step active"><i>3</i> Примените сферу</span><span class="step-line"></span><span class="step"><i>4</i> Внесите результат</span></div>${nextHTML()}<div class="workspace"><div class="stack"><section class="panel"><div class="panel-head"><h2><span>◇</span> Основа предмета</h2><span class="badge gray">БАЗА</span></div><div class="panel-body"><div class="field"><label>Тип предмета</label><button class="button secondary wide library-select" id="choose-base">${esc(g.name)} <span style="margin-left:auto">⌄</span></button></div><div class="field"><label>База предмета</label><button class="button secondary wide library-select" id="choose-base-2">${esc(b.name)} <span style="margin-left:auto">⌄</span></button></div><div class="two-fields"><div class="field"><label for="ilvl">Уровень предмета <span class="muted">· ilvl</span></label><input id="ilvl" type="number" min="1" max="100" value="${p.level}"></div><div class="field"><label for="budget-input">Бюджет, ex</label><input id="budget-input" type="number" min="0" max="1000000000000" value="${p.budget}"></div></div><div class="field"><label>Редкость</label><div class="radio-group">${[['normal','Обычный'],['magic','Магический'],['rare','Редкий']].map(([v,t])=>`<button data-rarity="${v}" class="${p.rarity===v?'active':''}">${t}</button>`).join('')}</div></div><label class="checkline"><input type="checkbox" id="corrupted" ${p.corrupted?'checked':''}> Осквернён</label><div class="item-card"><div class="item-name">${esc(b.name)}</div><div class="item-subtitle">${p.rarity==='unique'?'УНИКАЛЬНЫЙ':p.rarity==='rare'?'РЕДКИЙ':p.rarity==='magic'?'МАГИЧЕСКИЙ':'ОБЫЧНЫЙ'} ПРЕДМЕТ · ILVL ${p.level}</div>${art(b)}<div class="item-properties">${b.properties.filter(t=>!t.startsWith('Item Level')&&!t.includes('Base Movement')).slice(0,3).map(esc).join('<br>')}</div>${b.implicit.length||p.implicitRoll?`<div class="item-divider"></div><div class="item-implicit">${p.implicitRoll?esc(p.implicitRoll):b.implicit.map(esc).join('<br>')}</div>`:''}${ms.length?`<div class="item-divider"></div>${ms.map(m=>`<div class="item-mod">${esc(m.roll||m.text)}</div>`).join('')}`:''}</div><div class="section-note">Характеристики базы без учёта аффиксов. Значения в скобках — диапазоны тира.</div></div></section></div><div class="stack"><section class="panel"><div class="panel-head"><h2><span>≋</span> Текущие аффиксы</h2><span class="badge gray">${ms.length} / ${caps(p.rarity).reduce((a,b)=>a+b,0)}</span></div>${[1,2].map(kind=>`<div class="affix-group"><div class="affix-title ${kind===2?'suffix':''}"><span>${kind===1?'ПРЕФИКСЫ':'СУФФИКСЫ'}</span><span>${ms.filter(m=>m.kind===kind).length} / ${caps(p.rarity)[kind-1]}</span></div>${ms.filter(m=>m.kind===kind).map(m=>`<div class="affix-row ${kind===2?'suffix':''}"><span class="tier">T${tier(g,m)}</span><div class="affix-copy">${esc(m.roll||m.text)}<small>${esc(m.name)} · ilvl ${m.level}${m.fractured?' · 🔒 раскол':''}${m.crafted?' · crafted':''}${m.desecrated||m.source==='desecrated'?' · Бездна':''}</small></div><div class="row-tools"><button class="tiny-button" data-flags="${m.id}" aria-label="Признаки аффикса" title="Раскол, crafted, Бездна">◈</button><button class="tiny-button" data-edit="${m.id}" aria-label="Изменить аффикс" title="Изменить значение или тир">✎</button><button class="tiny-button" data-remove="${m.id}" aria-label="Удалить аффикс" title="Удалить">×</button></div></div>`).join('')}${Array.from({length:Math.max(0,caps(p.rarity)[kind-1]-ms.filter(m=>m.kind===kind).length)},(_,i)=>`<button class="empty-slot" data-add-kind="${kind}">＋ Добавить ${kind===1?'префикс':'суффикс'} <span style="float:right;color:#5e6c51">${i===0?'Свободный слот':'—'}</span></button>`).join('')}${caps(p.rarity)[kind-1]===0?'<div class="section-note" style="margin-bottom:15px">У обычной вещи нет явных аффиксов.</div>':''}</div>`).join('')}<div class="panel-foot"><span>◈ Группы модов проверяются автоматически</span><button class="text-button" id="clear-mods">Очистить</button></div></section><section class="panel"><div class="panel-head"><h2><span>◎</span> Что улучшать?</h2><button class="preset-link" id="presets">Подобрать статы ↗</button></div><div class="panel-body"><p class="section-note" style="margin-top:0">Выберите направление, чтобы получить стартовый набор целей для этой вещи. Приоритеты и тиры можно изменить.</p><div class="actions" style="margin-top:13px">${presetOptions().map(([id,name])=>`<button class="button secondary small" data-preset="${id}">${name} ↗</button>`).join('')}</div></div></section></div><div class="stack right-stack"><section class="panel"><div class="panel-head"><h2><span>✧</span> Желаемые статы</h2><span class="badge">ЦЕЛЬ</span></div><div class="panel-body">${gs.length?`<div class="progress-meta"><span>Достижение цели</span><strong>${countLabel()} статов</strong></div><div class="progress-track"><div style="width:${percent}%"></div></div>${gs.map(t=>`<div class="target-row"><span class="target-status ${t.met?'met':''}">${t.met?'✓':'·'}</span><div class="affix-copy">${esc(t.target?.text)}<small>T${tier(g,t.target)} и лучше · ${t.target?.kind===1?'префикс':'суффикс'}</small><select data-priority="${t.id}" aria-label="Приоритет цели">${[[3,'Обязательный'],[2,'Важный'],[1,'Желательный']].map(([v,l])=>`<option value="${v}" ${v===t.priority?'selected':''}>${l}</option>`).join('')}</select></div><div class="row-tools"><button class="tiny-button" data-target-edit="${t.id}" title="Изменить тир" aria-label="Изменить цель">✎</button><button class="tiny-button" data-target-remove="${t.id}" aria-label="Удалить цель">×</button></div></div>`).join('')}`:'<div class="section-note" style="margin:0 0 15px">Какой должна стать эта вещь? Добавьте нужные моды или подберите стартовый набор статов.</div>'}<button class="empty-slot" id="add-target" ${p.targets.length>=6?'disabled':''} style="margin-top:12px;margin-bottom:0">＋ Добавить желаемый стат</button></div></section><section class="panel"><div class="panel-head"><h2><span>◉</span> Вложенная валюта</h2><button class="text-button" id="go-journal" title="Открыть журнал">↗</button></div><div class="panel-body"><div class="mini-label">${spent.unknown?'ИЗВЕСТНАЯ СТОИМОСТЬ':'ВСЕГО ПОТРАЧЕНО'}</div><div class="budget-total">${fmt(spent.value)} <small>exalted</small></div><div class="currency-list">${currencySummary(p.entries)}</div>${!p.entries.length?'<p class="section-note" style="margin:0">Расходов пока нет. Запишите стоимость базы и использованные сферы.</p>':''}${spent.unknown?`<div class="inline-warning">${spent.unknown} записей без курса не входят в сумму. Укажите стоимость в журнале.</div>`:''}<div style="margin-top:18px" class="progress-meta"><span>Бюджет</span><strong class="${spent.value>p.budget?'budget-warn':''}">${fmt(spent.value)} / ${fmt(p.budget)} ex</strong></div><div class="progress-track"><div style="width:${p.budget?Math.min(100,spent.value/p.budget*100):0}%;${spent.value>p.budget?'background:#c89565':''}"></div></div><div class="budget-controls"><button class="button secondary" id="rates">Курсы валют</button><button class="button" id="add-entry">＋ Расход</button></div></div></section></div></div><div class="note-line"><span>ⓘ</span><span>Обычные и специальные аффиксы · PoE2DB, 08.11.2026. Вносите реальные исходы из игры. Доступность исторических валют зависит от лиги. Прогресс — соответствие целям, без расчёта вероятности или минимальной цены.</span></div>`}
function currencySummary(es){const counts=new Map();for(const e of es)counts.set(e.currency,(counts.get(e.currency)||0)+e.qty);return [...counts].slice(0,5).map(([c,q])=>`<span class="currency-chip" title="${esc(CURRENCIES.find(x=>x[0]===c)?.[1]||c)}"><i class="orb ${CURRENCIES.find(x=>x[0]===c)?.[2]||''}"></i>${fmt(q)} <span class="muted">${esc(({ 'Exalted Orb':'ex','Divine Orb':'div','Chaos Orb':'chaos','Regal Orb':'regal',Base:'база'})[c]||c.replace('Orb of ',''))}</span></span>`).join('')}
function nextHTML(){return workbench.nextHTML()}
function presetOptions(){const id=group().id;if(/Bows|Crossbows|Maces|Quarterstaves|Spears/.test(id))return [['physical','Физический урон'],['elemental','Стихийный урон']];if(/Wands|Staves|Foci/.test(id))return [['caster','Заклинания'],['defence','Защита']];if(id==='Sceptres')return [['minion','Прислужники'],['defence','Защита']];return [['defence','Жизнь и защита'],['energy','Энергощит / мана']]}
function suggested(mode){const g=group(),p=current();let scored=families(g).map(f=>{const m=f.tiers.find(m=>m.level<=p.level&&!m.source),k=f.key.toLowerCase(),t=(m?.text||'').toLowerCase();let score=0;if(mode==='physical'){if(k==='localphysicaldamagepercent')score=100;if(k==='physicaldamage')score=95;if(k.includes('physicaldamagepercentandaccuracy'))score=90;if(k==='increasedattackspeed')score=85;if(k.includes('criticalstrikechance'))score=80;if(k.includes('criticalstrikemultiplier'))score=75}if(mode==='elemental'){if(/^(fire|cold|lightning)damage$/.test(k)&&f.kind===1)score=95;if(/increasedweaponelementaldamagepercent/.test(k))score=90;if(k==='increasedattackspeed')score=85;if(k.includes('criticalstrikechance'))score=80;if(k.includes('criticalstrikemultiplier'))score=75}if(mode==='caster'){if(k==='increasesocketedgemlevel'&&/чародей|заклинан/.test(t))score=100;if(/spelldamage|weaponcasterdamageprefix/.test(k)&&/чар|заклинан/.test(t))score=90;if(/castspeed/.test(k))score=85;if(/critical.*spell|spell.*critical/.test(k))score=80;if(/mana/.test(k))score=60}if(mode==='minion'){if(k==='increasesocketedgemlevel'&&/приспешник|прислужник/.test(t))score=100;if(/spirit/.test(k))score=95;if(/minion/.test(k))score=85}if(mode==='defence'){if(k==='increasedlife')score=100;if(/^(baselocaldefences|defencespercent)$/.test(k))score=85;if(/fireresistance|coldresistance|lightningresistance/.test(k))score=80;if(/chaosresistance/.test(k))score=75;if(/movementvelocity/.test(k)||t.includes('скорости передвижения'))score=95}if(mode==='energy'){if(/^(baselocaldefences|defencespercent)$/.test(k)&&/щит/.test(t))score=100;if(k==='increasedmana')score=90;if(/castspeed/.test(k))score=80;if(/intelligence/.test(k))score=75;if(/resistance/.test(k))score=60}return {m,score}}).filter(x=>x.m&&x.score>0).sort((a,b)=>b.score-a.score);const out=[];for(const x of scored)if(allowed(x.m,out,'rare',p.level))out.push(x.m);return out.slice(0,6)}
function presetModal(mode){if(!mode){modal('Подобрать целевые статы',`<p class="modal-info">Это стартовые ориентиры по типу предмета. Лучший набор зависит от навыков и остальных вещей.</p><div class="actions">${presetOptions().map(([id,name])=>`<button class="button secondary" data-modal-preset="${id}">${name}</button>`).join('')}</div>`);document.querySelectorAll('[data-modal-preset]').forEach(b=>b.onclick=()=>presetModal(b.dataset.modalPreset));return}const list=suggested(mode);modal('Стартовый набор целей',`<p class="modal-info">${list.length?'Доступные на вашем ilvl обычные моды. Этот набор заменит текущие цели; имеющиеся аффиксы сохранятся.':'Для этого направления в пуле вещи нет подходящих модов. Добавьте цели вручную.'}</p>${list.map(m=>`<div class="target-row"><span class="badge ${m.kind===2?'purple':'gold'}">T${tier(group(),m)}</span><span>${esc(m.text)}</span></div>`).join('')}<p class="section-note">Тиры взяты из снимка каталога. Набор не является расчётом DPS или оптимизатором билда.</p>`,list.length?'<button class="button" id="apply-preset">Применить цели</button>':'');if(list.length)$('#apply-preset').onclick=()=>{current().targets=list.map((m,i)=>({id:m.id,priority:i<3?3:2}));save();$('#modal').close();toast('Цели обновлены')}}
function basePicker(newProject=false){modal(newProject?'Новый проект крафта':'Выбрать базу',`<div class="field"><label for="base-group">Тип предмета</label><select id="base-group">${DATA.groups.map(g=>`<option value="${g.id}" ${g.id===current().group?'selected':''}>${esc(g.name)}</option>`).join('')}</select></div><input class="search-input" id="base-search" placeholder="Поиск по названию базы…" aria-label="Поиск базы"><div class="picker-list" id="base-results"></div>`);const fill=()=>{const g=DATA.groups.find(g=>g.id===$('#base-group').value),q=$('#base-search').value.toLowerCase();$('#base-results').innerHTML=g.bases.filter(b=>(b.name+' '+b.id).toLowerCase().includes(q)).map(b=>`<button class="picker-option" data-base="${b.id}"><img src="${esc(b.img)}" alt=""><span class="affix-copy">${esc(b.name)}<small>${b.properties.filter(t=>!t.startsWith('Item Level')).slice(0,2).map(esc).join(' · ')}</small>${b.implicit.length?`<small>${esc(b.implicit[0])}</small>`:''}</span></button>`).join('')||'<p class="empty-state">Базы не найдены</p>';document.querySelectorAll('[data-base]').forEach(el=>el.onclick=()=>{const choose=()=>{if(newProject){const p=blank(g.id,el.dataset.base);p.name=g.bases.find(b=>b.id===p.base).name;store.projects.unshift(p);store.active=p.id}else {current().group=g.id;current().base=el.dataset.base;current().mods=[];current().targets=[];current().augments=[];current().sockets=0;current().quality=0;current().history=[];delete current().lastOutcome;delete current().enchantments}page='craft';save();$('#modal').close()};if(!newProject&&(current().mods.length||current().targets.length)){modal('Сменить основу?',`<p class="modal-info">Новая база: <strong>${esc(g.bases.find(b=>b.id===el.dataset.base).name)}</strong>. Текущие аффиксы и цели будут очищены. Журнал расходов останется в проекте.</p>`,'<button class="button secondary" id="cancel-change">Отмена</button><button class="button" id="confirm-change">Сменить базу</button>');$('#confirm-change').onclick=choose;$('#cancel-change').onclick=()=>basePicker(newProject)}else choose()})};$('#base-group').onchange=()=>{$('#base-search').value='';fill()};$('#base-search').oninput=fill;fill()}
function affixPicker(kind,target=false,editing){const p=current(),g=group();const existing=target?p.targets.filter(x=>x.id!==editing).map(x=>g.mods.find(m=>m.id===x.id)):mods().filter(x=>x.id!==editing);const rarity=target?'rare':p.rarity;modal(target?'Выбрать желаемый стат':'Добавить аффикс',`<p class="modal-info">${target?'Выберите семейство, затем минимально желаемый тир.':'Показаны совместимые группы обычных модов для вашей базы.'} Уровень предмета: ${p.level}.</p><input class="search-input" id="mod-search" placeholder="Урон, скорость, сопротивление…" aria-label="Поиск аффикса"><div class="picker-list" id="mod-results"></div>`);const fill=()=>{const q=$('#mod-search').value.toLowerCase();const fs=families({mods:g.mods.filter(m=>m.source!=='unrevealed')}).filter(f=>!kind||f.kind===kind).map(f=>({...f,available:f.tiers.filter(m=>allowed(m,existing,rarity,target||m.crafted?100:p.level)&&(target||!m.crafted||existing.filter(m=>m.crafted).length<craftedLimit(p,g)))})).filter(f=>f.available.length&&(f.available[0].text+' '+f.key+' '+f.available.map(m=>m.name).join(' ')).toLowerCase().includes(q));$('#mod-results').innerHTML=fs.map((f,i)=>`<button class="picker-option" data-family="${i}"><span class="badge ${f.kind===2?'purple':'gold'}">${f.kind===1?'П':'С'}</span><span class="affix-copy">${esc(f.available[0].text)}<small>${f.available.length} тиров доступно · ${f.kind===1?'префикс':'суффикс'}</small></span><span>›</span></button>`).join('')||'<div class="empty-state">Нет подходящих модов. Проверьте ilvl, свободные слоты и уже занятые группы.</div>';document.querySelectorAll('[data-family]').forEach(el=>el.onclick=()=>tierPicker(fs[+el.dataset.family],target,editing))};$('#mod-search').oninput=fill;fill()}
function tierPicker(f,target,editing){const g=group(),p=current(),old=p.mods.find(x=>x.id===editing);modal(target?'Минимальный желаемый тир':'Тир и значение аффикса',`<div class="field"><label for="mod-tier">Тир · требуемый ilvl</label><select id="mod-tier">${f.available.map(m=>`<option value="${m.id}" ${m.id===editing?'selected':''}>T${tier(g,m)} · ilvl ${m.level} · ${esc(m.text)}</option>`).join('')}</select></div>${!target?`<div class="field"><label for="actual-roll">Фактический стат целиком, если известен</label><input id="actual-roll" maxlength="500" value="${esc(old?.roll||'')}" placeholder="Например: 145% увеличение физического урона"><p class="section-note">Оставьте пустым, чтобы показывать диапазон тира. Ручной текст — подпись; соответствие цели определяется выбранным тиром.</p></div>`:'<p class="modal-info">Цель считается достигнутой, когда на предмете есть это семейство с выбранным или более высоким тиром.</p>'}`,`<button class="button secondary" id="back-affix">← Назад</button><button class="button" id="confirm-affix">${editing?'Сохранить':'Добавить'}</button>`);$('#back-affix').onclick=()=>affixPicker(f.kind,target,editing);$('#confirm-affix').onclick=()=>{const id=$('#mod-tier').value,list=target?p.targets:p.mods;const previous=list.find(x=>x.id===editing);if(editing)list.splice(list.findIndex(x=>x.id===editing),1);const definition=g.mods.find(m=>m.id===id);list.push(target?{id,priority:previous?.priority||2}:{...previous,id,roll:$('#actual-roll').value.trim(),crafted:previous?.crafted??!!definition.crafted,desecrated:previous?.desecrated??definition.source==='desecrated'});save();$('#modal').close();toast(target?'Цель добавлена':'Аффикс сохранён')}}
function entryModal(currency='Exalted Orb',editIndex){const p=current(),old=editIndex!==undefined?p.entries[editIndex]:null;currency=old?.currency||currency;modal(old?'Изменить расход':'Записать расход',`<div class="field"><label for="entry-currency">Валюта / расход</label><select id="entry-currency">${CURRENCIES.map(([id,name])=>`<option value="${id}" ${id===currency?'selected':''}>${name} · ${id}</option>`).join('')}</select></div><div class="two-fields"><div class="field"><label for="entry-qty">Количество</label><input id="entry-qty" type="number" min="0.001" max="1000000000" step="any" value="${old?.qty||1}"></div><div class="field"><label for="entry-rate">Цена одной единицы, ex</label><input id="entry-rate" type="number" min="0" max="1000000000" step="any" value="${old?old.rate??'':store.rates[currency]??''}" placeholder="Укажите курс"></div></div><div class="field"><label for="entry-note">Комментарий</label><input id="entry-note" maxlength="500" placeholder="Покупка базы, добавление мода…" value="${esc(old?.note||'')}"></div><p class="section-note">Курс фиксируется в записи. Пустая цена означает неизвестную стоимость; она не входит в итог. Состояние предмета меняется отдельно.</p><div id="entry-error" class="error"></div>`,'<button class="button" id="confirm-entry">Сохранить расход</button>');$('#entry-currency').onchange=()=>{$('#entry-rate').value=store.rates[$('#entry-currency').value]??''};$('#confirm-entry').onclick=()=>{const qty=+$('#entry-qty').value,rate=$('#entry-rate').value===''?null:+$('#entry-rate').value;if(!Number.isFinite(qty)||qty<=0||qty>1e9||(rate!==null&&(!Number.isFinite(rate)||rate<0||rate>1e9))){$('#entry-error').textContent='Укажите положительное количество и корректную цену.';return}const e={currency:$('#entry-currency').value,qty,rate,note:$('#entry-note').value.trim(),date:old?.date||new Date().toISOString()};if(old)p.entries[editIndex]=e;else p.entries.push(e);save();$('#modal').close();toast('Расход сохранён')}}
function ratesModal(){modal('Ваши курсы валют',`<p class="modal-info">Стоимость одной единицы в Exalted Orb. Укажите свои цены для своей лиги. Рыночные котировки автоматически не загружаются.</p><div class="picker-list" style="max-height:45vh">${CURRENCIES.filter(x=>x[0]!=='Exalted Orb'&&(current().entries.some(e=>e.currency===x[0])||store.rates[x[0]]!==undefined||['Chaos Orb','Divine Orb','Regal Orb','Orb of Augmentation','Orb of Transmutation','Orb of Annulment'].includes(x[0]))).map(([id,name])=>`<div class="field"><label>${name} · ${id}</label><input data-rate="${id}" type="number" min="0" max="1000000000" step="any" value="${store.rates[id]??''}" placeholder="Не указан"></div>`).join('')}</div><p class="section-note">Новые курсы подставляются в будущие расходы. Старые записи сохраняют свою цену; изменить её можно в журнале.</p><p id="rate-error" class="error"></p>`,'<button class="button" id="save-rates">Сохранить курсы</button>');$('#save-rates').onclick=()=>{const next={...store.rates};for(const el of document.querySelectorAll('[data-rate]')){if(el.value===''){delete next[el.dataset.rate];continue}const n=+el.value;if(!Number.isFinite(n)||n<0||n>1e9){$('#rate-error').textContent='Курс должен быть числом от 0 до 1 000 000 000.';return}next[el.dataset.rate]=n}store.rates=next;persist();$('#modal').close();toast('Курсы сохранены')}}
function projectsHTML(){return `<div class="page-heading"><div><div class="eyebrow">КАЖДАЯ ВЕЩЬ — СВОЯ ИСТОРИЯ</div><h1>Мои проекты</h1><p>Вернитесь к крафту с того места, где остановились.</p></div><button class="button secondary" id="import">↧ Импорт JSON</button></div><div class="filter-bar"><input class="search-input" id="project-search" placeholder="Найти проект…" aria-label="Поиск проекта"><span class="muted">${store.projects.length} проектов на этом устройстве</span></div><div class="project-grid">${store.projects.map(p=>{const g=DATA.groups.find(g=>g.id===p.group),b=g.bases.find(b=>b.id===p.base),v=total(p.entries);return `<section class="panel project-tile" data-project-card="${esc(p.name.toLowerCase())}"><div class="progress-meta"><span>${esc(g.name)}</span><span class="badge gray">ILVL ${p.level}</span></div>${art(b)}<h2>${esc(p.name)}</h2><p class="muted">${esc(b.name)}</p><div class="progress-meta"><span>${p.mods.length} аффиксов · ${p.targets.length} целей</span><strong>${fmt(v.value)} ex${v.unknown?' + ?':''}</strong></div><div class="actions"><button class="button small" data-open-project="${p.id}">Продолжить крафт ↗</button><button class="icon-button" data-duplicate="${p.id}" title="Копировать" aria-label="Копировать проект">⧉</button><button class="icon-button" data-delete-project="${p.id}" title="Удалить" aria-label="Удалить проект">×</button></div></section>`}).join('')}</div>`}
function journalHTML(){const p=current(),spent=total(p.entries);return `<div class="page-heading"><div><div class="eyebrow">У КАЖДОГО УЛУЧШЕНИЯ ЕСТЬ ЦЕНА</div><h1>Журнал валюты</h1><p>Расходы проекта «${esc(p.name)}». Цены фиксируются в момент записи.</p></div><div class="actions"><button class="button secondary" id="rates">Курсы валют</button><button class="button" id="add-entry">＋ Записать расход</button></div></div><div class="stats-row"><section class="panel stat"><span class="mini-label">ИЗВЕСТНАЯ СТОИМОСТЬ</span><strong>${fmt(spent.value)} <small>exalted</small></strong></section><section class="panel stat"><span class="mini-label">ОСТАТОК БЮДЖЕТА</span><strong>${fmt(p.budget-spent.value)} <small>exalted</small></strong></section><section class="panel stat"><span class="mini-label">ЗАПИСЕЙ БЕЗ КУРСА</span><strong>${spent.unknown} <small>не включены в стоимость</small></strong></section></div><section class="panel">${p.entries.length?`<div style="overflow:auto"><table class="journal-table"><thead><tr><th>Валюта</th><th>Количество</th><th>Курс / ex</th><th>Стоимость</th><th class="note-col">Комментарий</th><th></th></tr></thead><tbody>${p.entries.map((e,i)=>`<tr><td><i class="orb ${CURRENCIES.find(c=>c[0]===e.currency)?.[2]||''}"></i>${esc(CURRENCIES.find(c=>c[0]===e.currency)?.[1]||e.currency)}</td><td>${fmt(e.qty)}</td><td>${e.rate===null?'—':fmt(e.rate)}</td><td>${e.rate===null?'<span class="budget-warn">Нет курса</span>':fmt(e.qty*e.rate)+' ex'}</td><td class="note-col muted">${esc(e.note||'—')}</td><td><div class="actions"><button class="tiny-button" data-edit-entry="${i}" aria-label="Изменить запись">✎</button><button class="tiny-button" data-delete-entry="${i}" aria-label="Удалить запись">×</button></div></td></tr>`).reverse().join('')}</tbody></table></div>`:'<div class="empty-state"><div style="font-size:35px">◉</div><h2>Начните историю крафта</h2><p>Запишите стоимость базы и использованную валюту.</p><button class="button" id="empty-add-entry">＋ Первый расход</button></div>'}</section><div class="note-line"><span>ⓘ</span><span>Сумма относится только к текущему проекту. Внесение расхода не применяет сферу к предмету.</span></div>`}
function bind(){const on=(s,fn)=>{const el=$(s);if(el)el.onclick=fn};on('#choose-base',()=>basePicker());on('#choose-base-2',()=>basePicker());on('#add-target',()=>affixPicker(null,true));on('#presets',()=>presetModal());on('#rates',ratesModal);on('#add-entry',()=>entryModal());on('#empty-add-entry',()=>entryModal());on('#go-journal',()=>{page='journal';render()});on('#next-record',()=>{const c=$('#next-record').dataset.currency;if(c==='Other'){if(!current().targets.length)presetModal();else {page='journal';render()}}else outcomePicker(c)});on('#import',()=>$('#import-file').click());on('#clear-mods',()=>{if(!current().mods.length)return;modal('Очистить аффиксы?',`<p class="modal-info">Будут удалены все ${current().mods.length} текущих аффикса. Цели и расходы сохранятся.</p>`,'<button class="button" id="confirm-clear">Очистить аффиксы</button>');$('#confirm-clear').onclick=()=>{current().mods=[];save();$('#modal').close()}});
 const name=$('#project-name');if(name)name.onchange=()=>{current().name=name.value.trim()||'Без названия';save(false)};
 const ilvl=$('#ilvl');if(ilvl)ilvl.onchange=()=>{const n=+ilvl.value;if(!Number.isInteger(n)||n<1||n>100){ilvl.value=current().level;toast('ilvl должен быть целым числом от 1 до 100');return}if(mods().some(m=>m.level>n&&!m.crafted)){ilvl.value=current().level;toast('Сначала исправьте обычные аффиксы, требующие более высокого ilvl');return}current().level=n;save()};
 const budget=$('#budget-input');if(budget)budget.onchange=()=>{const n=+budget.value;if(!Number.isFinite(n)||n<0||n>1e12){budget.value=current().budget;return}current().budget=n;save()};const corr=$('#corrupted');if(corr)corr.onchange=()=>{current().corrupted=corr.checked;save()};
 document.querySelectorAll('[data-rarity]').forEach(el=>el.onclick=()=>{const c=caps(el.dataset.rarity);if([1,2].some(k=>mods().filter(m=>m.kind===k).length>c[k-1])){toast('Сначала удалите лишние аффиксы для этой редкости');return}current().rarity=el.dataset.rarity;save()});
 document.querySelectorAll('[data-add-kind]').forEach(el=>el.onclick=()=>affixPicker(+el.dataset.addKind));document.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{current().mods=current().mods.filter(x=>x.id!==el.dataset.remove);save()});document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>{const f=families(group()).find(f=>f.tiers.some(m=>m.id===el.dataset.edit));tierPicker({...f,available:f.tiers.filter(m=>m.level<=current().level)},false,el.dataset.edit)});
 document.querySelectorAll('[data-target-remove]').forEach(el=>el.onclick=()=>{current().targets=current().targets.filter(x=>x.id!==el.dataset.targetRemove);save()});document.querySelectorAll('[data-target-edit]').forEach(el=>el.onclick=()=>{const f=families(group()).find(f=>f.tiers.some(m=>m.id===el.dataset.targetEdit));tierPicker({...f,available:f.tiers},true,el.dataset.targetEdit)});document.querySelectorAll('[data-priority]').forEach(el=>el.onchange=()=>{current().targets.find(x=>x.id===el.dataset.priority).priority=+el.value;save(false)});document.querySelectorAll('[data-preset]').forEach(el=>el.onclick=()=>presetModal(el.dataset.preset));
 document.querySelectorAll('[data-open-project]').forEach(el=>el.onclick=()=>{store.active=el.dataset.openProject;page='craft';persist();render()});document.querySelectorAll('[data-duplicate]').forEach(el=>el.onclick=()=>{const old=store.projects.find(p=>p.id===el.dataset.duplicate),p=structuredClone(old);p.id=crypto.randomUUID();p.name=(p.name+' · копия').slice(0,120);p.updated=Date.now();store.projects.unshift(p);persist();render();toast('Создана копия с аффиксами, целями и расходами')});document.querySelectorAll('[data-delete-project]').forEach(el=>el.onclick=()=>{const p=store.projects.find(p=>p.id===el.dataset.deleteProject);modal('Удалить проект?',`<p class="modal-info">«${esc(p.name)}» и его журнал будут удалены с устройства. Экспортируйте проект, если хотите сохранить копию.</p>`,'<button class="button secondary" id="cancel-delete">Отмена</button><button class="button" id="confirm-delete">Удалить проект</button>');$('#cancel-delete').onclick=()=>$('#modal').close();$('#confirm-delete').onclick=()=>{store.projects=store.projects.filter(x=>x.id!==p.id);if(!store.projects.length)store.projects=[blank()];if(store.active===p.id)store.active=store.projects[0].id;persist();render();$('#modal').close()}});
 const search=$('#project-search');if(search)search.oninput=()=>document.querySelectorAll('[data-project-card]').forEach(el=>el.hidden=!el.dataset.projectCard.includes(search.value.toLowerCase()));
 document.querySelectorAll('[data-edit-entry]').forEach(el=>el.onclick=()=>entryModal('Exalted Orb',+el.dataset.editEntry));document.querySelectorAll('[data-delete-entry]').forEach(el=>el.onclick=()=>{const i=+el.dataset.deleteEntry;modal('Удалить расход?',`<p class="modal-info">Запись на ${fmt(current().entries[i].qty)} ${esc(current().entries[i].currency)} будет удалена из журнала.</p>`,'<button class="button" id="confirm-delete-entry">Удалить запись</button>');$('#confirm-delete-entry').onclick=()=>{current().entries.splice(i,1);save();$('#modal').close()}})
}
document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;render()});$('#new-project').onclick=()=>basePicker(true);$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({format:'wraeclast-forge',version:1,project:current()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=current().name.replace(/[^\p{L}\p{N}_-]/gu,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Проект экспортирован')};$('#import-file').onchange=async()=>{const file=$('#import-file').files[0];if(!file)return;try{if(file.size>3e6)throw Error('Файл слишком большой');const obj=JSON.parse(await file.text());if(obj.format!=='wraeclast-forge'||obj.version!==1)throw Error('Формат проекта не поддерживается');const p=validateProject(obj.project,DATA);store.projects.unshift(p);store.active=p.id;page='craft';save();toast('Проект импортирован')}catch(e){toast('Импорт: '+e.message)}$('#import-file').value=''};
$('#data-info').onclick=()=>modal('Данные и возможности',`<div class="modal-info"><p><strong>Wraeclast Forge v1.0.0.</strong> Пошаговая запись фактического крафта экипировки: обычные, Greater и Perfect сферы, эссенции и сплавы, совместимые омены, отмена, раскол, Divine, Бездна, качество, катализаторы, Augment и особые операции.</p><p>Каталог: <a href="https://poe2db.tw/ru/Modifiers" target="_blank" rel="noopener">PoE2DB</a>, снимок от 8 ноября 2026. Дата снимка не является версией патча. Отключённые механики находятся в архивном режиме; Standard-only омены доступны при соответствующем режиме. Наличие записи не гарантирует доступность в вашей лиге.</p><p>Помощник не генерирует RNG и не знает результат до применения в игре. Для непредсказуемых Vaal, Architect и рунной ковки вы вручную вносите итоговое состояние. Рекомбинатор доступен только для записи исторических результатов. Вероятности, DPS и минимальная рыночная цена не рассчитываются.</p><p>Homogenising проверяется по явным тегам аффиксов. Для специальных баз вручную укажите максимум гнёзд в состоянии предмета. Качество и особые эффекты сохраняются, но полные итоговые характеристики предмета не вычисляются.</p><p>Проекты, признаки модов и история сохраняются на этом устройстве. Экспорт JSON переносит проект; импорт старой версии поддерживается. Материалы PoE2DB: <a href="https://creativecommons.org/licenses/by-nc-sa/3.0/" target="_blank" rel="noopener">CC BY-NC-SA 3.0</a>. Изображения и игровые материалы принадлежат соответствующим правообладателям, включая Grinding Gear Games.</p></div>`);
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
const workbench=createWorkbench({$,esc,modal,toast,current,group,save,store,chooseGoals:()=>presetModal(),replaceProject:(next,opts={})=>{if(opts.copy){next.id=crypto.randomUUID();next.name=(next.name+' · зеркальная копия').slice(0,120);store.projects.unshift(next);store.active=next.id}else store.projects[store.projects.findIndex(p=>p.id===next.id)]=next;save()}});
persist();render();

